// Generated by OrchestKit Claude Plugin
// Created: 2026-10-09

/**
 * No hook may emit a literal system-reminder tag (#4689).
 *
 * Claude Code 2.1.292 escapes system-reminder tags in hook output, so a hook
 * that wraps its additionalContext in one now reaches the model as visible
 * literal markup instead of a reminder. CC adds its own wrapper; hook text
 * must be plain.
 *
 * This scans every non-test handler source for the tag inside code (comments
 * stripped) and allows zero hits outside DETECTORS: files that only MATCH the
 * tag in incoming prompt text and never emit it.
 */

import { describe, it, expect } from 'vitest';
import { readFileSync, readdirSync, statSync } from 'node:fs';
import { join, relative } from 'node:path';

const SRC = join(__dirname, '..');
const TAG = '<system-reminder';

// Files that read the tag out of incoming text and never put it in output.
const DETECTORS = new Set(['prompt/cache-break-detector.ts']);

function walk(dir: string, out: string[] = []): string[] {
  for (const name of readdirSync(dir)) {
    const p = join(dir, name);
    if (statSync(p).isDirectory()) {
      if (name === 'node_modules' || name === '__tests__') continue;
      walk(p, out);
    } else if (name.endsWith('.ts') && !name.endsWith('.test.ts') && !name.endsWith('.d.ts')) {
      out.push(p);
    }
  }
  return out;
}

function stripComments(src: string): string {
  return src
    .replace(/\/\*[\s\S]*?\*\//g, '')
    .replace(/^\s*\/\/.*$/gm, '');
}

describe('hook output carries no literal system-reminder tag (CC 2.1.292, #4689)', () => {
  const files = walk(SRC);

  it('scans the handler tree', () => {
    expect(files.length).toBeGreaterThan(50);
  });

  it('no non-detector source has the tag in code', () => {
    const hits = files
      .map((f) => relative(SRC, f))
      .filter((rel) => !DETECTORS.has(rel))
      .filter((rel) => stripComments(readFileSync(join(SRC, rel), 'utf8')).includes(TAG));
    expect(hits).toEqual([]);
  });

  it('every listed detector still exists and still matches the tag', () => {
    for (const rel of DETECTORS) {
      expect(stripComments(readFileSync(join(SRC, rel), 'utf8'))).toContain(TAG);
    }
  });
});
